/// Decodes a Attachment from JSON format.
pub fn from_json_attachment(json: &str) -> std::result::Result<Attachment, String> {
    let parsed: serde_json::Value = serde_json::from_str(json)
        .map_err(|e| format!("JSON parse error: {}", e))?;

    let obj = parsed.as_object()
        .ok_or_else(|| "expected JSON object".to_string())?;

    // Check for unknown fields (strict mode). Use a match on a static
    // slice instead of a HashSet — for the typical small field count
    // (<20) the linear scan is faster and avoids the per-call HashSet
    // allocation that the previous codegen emitted.
    for key in obj.keys() {
        match key.as_str() {
            "id" => {},
            "filename" => {},
            "mime_type" => {},
            "size_bytes" => {},
            "checksum" => {},
            "url" => {},
            "uploaded_at" => {},
            other => return Err(format!("unknown field: {}", other)),
        }
    }

    let mut msg: Attachment = Default::default();

    // Decode fields

    if let Some(value) = obj.get("id") {
        msg.id = value.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
    }

    if let Some(value) = obj.get("filename") {
        msg.filename = value.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
    }

    if let Some(value) = obj.get("mime_type") {
        msg.mime_type = value.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
    }

    if let Some(value) = obj.get("size_bytes") {
        msg.size_bytes = cramberry::json::parse_i64_from_json(value)?;
    }

    if let Some(value) = obj.get("checksum") {
        let s = value.as_str().ok_or_else(|| "expected string".to_string())?;
        msg.checksum = cramberry::json::decode_base64(s).map_err(|e| e.to_string())?;
    }

    if let Some(value) = obj.get("url") {
        if value.is_null() {
            msg.url = None;
        } else {
            let mut v: String = Default::default();
                    v = value.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
            msg.url = Some(v);
        }
    }

    if let Some(value) = obj.get("uploaded_at") {
        msg.uploaded_at = from_json_timestamp(&value.to_string()).map_err(|e| e.to_string())?;
    }


    Ok(msg)
}


