/// Event represents a system event.
#[derive(Debug, Clone, PartialEq, Default)]
#[derive(Serialize, Deserialize)]
pub struct Event {
    #[serde(rename = "id")]
    pub id: String,
    #[serde(rename = "type")]
    pub r#type: EventType,
    #[serde(rename = "entity_type")]
    pub entity_type: String,
    #[serde(rename = "entity_id")]
    pub entity_id: String,
    #[serde(rename = "source")]
    pub source: EventSource,
    #[serde(rename = "timestamp")]
    pub timestamp: Timestamp,
    #[serde(rename = "attributes")]
    pub attributes: std::collections::HashMap<String, String>,
    #[serde(rename = "payload")]
    pub payload: Option<Vec<u8>>,
    #[serde(rename = "correlation_id")]
    pub correlation_id: Option<String>,
    #[serde(rename = "causation_id")]
    pub causation_id: Option<String>,
}

/// Encodes a Event to the writer.
pub fn encode_event(writer: &mut Writer, msg: &Event) -> Result<()> {

    // Field 1: id
    if !msg.id.is_empty() {
        writer.write_tag(1, WireType::Bytes)?;
        writer.write_string(&msg.id)?;
    }

    // Field 2: type
    writer.write_tag(2, WireType::SVarint)?;
    writer.write_svarint(msg.r#type as i32)?;

    // Field 3: entity_type
    if !msg.entity_type.is_empty() {
        writer.write_tag(3, WireType::Bytes)?;
        writer.write_string(&msg.entity_type)?;
    }

    // Field 4: entity_id
    if !msg.entity_id.is_empty() {
        writer.write_tag(4, WireType::Bytes)?;
        writer.write_string(&msg.entity_id)?;
    }

    // Field 5: source
    writer.write_tag(5, WireType::Bytes)?;
    {
        let __cp = writer.begin_message();
        encode_event_source(writer, &msg.source)?;
        writer.end_message(__cp);
        Ok::<(), cramberry::Error>(())
    }?;

    // Field 6: timestamp
    writer.write_tag(6, WireType::Bytes)?;
    {
        let __cp = writer.begin_message();
        encode_timestamp(writer, &msg.timestamp)?;
        writer.end_message(__cp);
        Ok::<(), cramberry::Error>(())
    }?;

    // Field 7: attributes
    writer.write_tag(7, WireType::Bytes)?;
    {
        use cramberry::CompareKeys;
        let mut __entries: Vec<_> = msg.attributes.iter().collect();
        __entries.sort_by(|a, b| a.0.cramberry_cmp(b.0));
        let __cp = writer.begin_message();
        writer.write_varint(__entries.len() as u32)?;
        for (k, v) in __entries {
            writer.write_string(k)?;
            writer.write_string(v)?;
        }
        writer.end_message(__cp);
        Ok::<(), cramberry::Error>(())
    }?;

    // Field 8: payload
    if msg.payload.is_some() {
        writer.write_tag(8, WireType::Bytes)?;
        {
        let __inner = msg.payload.as_ref().unwrap();
        writer.write_length_prefixed_bytes(&(*__inner))
    }?;
    }

    // Field 9: correlation_id
    if msg.correlation_id.is_some() {
        writer.write_tag(9, WireType::Bytes)?;
        {
        let __inner = msg.correlation_id.as_ref().unwrap();
        writer.write_string(&(*__inner))
    }?;
    }

    // Field 10: causation_id
    if msg.causation_id.is_some() {
        writer.write_tag(10, WireType::Bytes)?;
        {
        let __inner = msg.causation_id.as_ref().unwrap();
        writer.write_string(&(*__inner))
    }?;
    }

    // End marker
    writer.write_end_marker()?;
    Ok(())
}

/// Decodes a Event from the reader.
pub fn decode_event(reader: &mut Reader) -> Result<Event> {
    let mut id: String = Default::default();
    let mut r#type: EventType = Default::default();
    let mut entity_type: String = Default::default();
    let mut entity_id: String = Default::default();
    let mut source: EventSource = Default::default();
    let mut timestamp: Timestamp = Default::default();
    let mut attributes: std::collections::HashMap<String, String> = Default::default();
    let mut payload: Option<Vec<u8>> = Default::default();
    let mut correlation_id: Option<String> = Default::default();
    let mut causation_id: Option<String> = Default::default();

    loop {
        let tag = reader.read_tag()?;
        if tag.field_number == 0 { break; } // End marker

        match tag.field_number {
            1 => id = reader.read_string()?.to_string(),
            2 => r#type = EventType::from_i32(reader.read_svarint()?).unwrap_or(EventType::Created),
            3 => entity_type = reader.read_string()?.to_string(),
            4 => entity_id = reader.read_string()?.to_string(),
            5 => source = {
            let __data = reader.read_length_prefixed_bytes()?;
            let mut __sub = Reader::new(__data);
            decode_event_source(&mut __sub)?
        },
            6 => timestamp = {
            let __data = reader.read_length_prefixed_bytes()?;
            let mut __sub = Reader::new(__data);
            decode_timestamp(&mut __sub)?
        },
            7 => attributes = {
            let __data = reader.read_length_prefixed_bytes()?;
            let mut reader = Reader::new(__data);
            let len = reader.read_varint()? as usize;
            let mut result = std::collections::HashMap::with_capacity(len);
            for _ in 0..len {
                let k = reader.read_string()?.to_string();
                let v = reader.read_string()?.to_string();
                result.insert(k, v);
            }
            result
        },
            8 => payload = Some(reader.read_length_prefixed_bytes()?.to_vec()),
            9 => correlation_id = Some(reader.read_string()?.to_string()),
            10 => causation_id = Some(reader.read_string()?.to_string()),
            _ => reader.skip_value(tag.wire_type)?,
        }
    }

    Ok(Event {
        id,
        r#type,
        entity_type,
        entity_id,
        source,
        timestamp,
        attributes,
        payload,
        correlation_id,
        causation_id,
    })
}

/// Marshals a Event to bytes.
pub fn marshal_event(msg: &Event) -> Result<Vec<u8>> {
    let mut writer = Writer::new();
    encode_event(&mut writer, msg)?;
    Ok(writer.into_bytes())
}

/// Unmarshals a Event from bytes.
pub fn unmarshal_event(data: &[u8]) -> Result<Event> {
    let mut reader = Reader::new(data);
    decode_event(&mut reader)
}

/// Encodes a Event to deterministic JSON format.
pub fn to_json_event(msg: &Event) -> std::result::Result<String, String> {
    let mut result = String::new();
    result.push_str("{");

    result.push_str("\"id\":");
    result.push_str(&cramberry::json::escape_json_string(&msg.id));

    result.push_str(",");
    result.push_str("\"type\":");
    result.push_str("\"");
    result.push_str(match msg.r#type {
        EventType::Created => "CREATED",
        EventType::Updated => "UPDATED",
        EventType::Deleted => "DELETED",
        EventType::Viewed => "VIEWED",
        EventType::Shared => "SHARED",
        _ => "UNKNOWN",
    });
    result.push_str("\"");

    result.push_str(",");
    result.push_str("\"entity_type\":");
    result.push_str(&cramberry::json::escape_json_string(&msg.entity_type));

    result.push_str(",");
    result.push_str("\"entity_id\":");
    result.push_str(&cramberry::json::escape_json_string(&msg.entity_id));

    result.push_str(",");
    result.push_str("\"source\":");
    result.push_str(&to_json_event_source(&msg.source)?);

    result.push_str(",");
    result.push_str("\"timestamp\":");
    result.push_str(&to_json_timestamp(&msg.timestamp)?);

    result.push_str(",");
    result.push_str("\"attributes\":");
    {
        result.push_str("{");
        let mut keys: Vec<String> = msg.attributes.keys().map(|k| k.to_string()).collect();
        cramberry::json::sort_map_keys_lexicographic(&mut keys);
        for (i, key_str) in keys.iter().enumerate() {
            if i > 0 { result.push_str(","); }
            result.push_str(&cramberry::json::escape_json_string(key_str));
            result.push_str(":");
            let k = key_str.as_str();
            let v = msg.attributes.get(k).unwrap();
            result.push_str(&cramberry::json::escape_json_string(&(*v)));
        }
        result.push_str("}");
    }

    result.push_str(",");
    result.push_str("\"payload\":");
    if let Some(v) = &msg.payload {
            result.push_str("\"");
        result.push_str(&cramberry::json::encode_base64(&v));
        result.push_str("\"");
    } else {
        result.push_str("null");
    }

    result.push_str(",");
    result.push_str("\"correlation_id\":");
    if let Some(v) = &msg.correlation_id {
            result.push_str(&cramberry::json::escape_json_string(&v));
    } else {
        result.push_str("null");
    }

    result.push_str(",");
    result.push_str("\"causation_id\":");
    if let Some(v) = &msg.causation_id {
            result.push_str(&cramberry::json::escape_json_string(&v));
    } else {
        result.push_str("null");
    }

    result.push_str("}");
    Ok(result)
}

/// Decodes a Event from JSON format.
pub fn from_json_event(json: &str) -> std::result::Result<Event, String> {
    let parsed: serde_json::Value = serde_json::from_str(json)
        .map_err(|e| format!("JSON parse error: {}", e))?;

    let obj = parsed.as_object()
        .ok_or_else(|| "expected JSON object".to_string())?;

    // Check for unknown fields (strict mode). Use a match on a static
    // slice instead of a HashSet — for the typical small field count
    // (<20) the linear scan is faster and avoids the per-call HashSet
    // allocation that the previous codegen emitted.
    for key in obj.keys() {
        match key.as_str() {
            "id" => {},
            "type" => {},
            "entity_type" => {},
            "entity_id" => {},
            "source" => {},
            "timestamp" => {},
            "attributes" => {},
            "payload" => {},
            "correlation_id" => {},
            "causation_id" => {},
            other => return Err(format!("unknown field: {}", other)),
        }
    }

    let mut msg: Event = Default::default();

    // Decode fields

    if let Some(value) = obj.get("id") {
        msg.id = value.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
    }

    if let Some(value) = obj.get("type") {
        let str_val = value.as_str().ok_or_else(|| "expected string for enum".to_string())?;
        msg.r#type = match str_val {
            "CREATED" => EventType::Created,
            "UPDATED" => EventType::Updated,
            "DELETED" => EventType::Deleted,
            "VIEWED" => EventType::Viewed,
            "SHARED" => EventType::Shared,
            _ => return Err(format!("unknown enum value: {}", str_val)),
        };
    }

    if let Some(value) = obj.get("entity_type") {
        msg.entity_type = value.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
    }

    if let Some(value) = obj.get("entity_id") {
        msg.entity_id = value.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
    }

    if let Some(value) = obj.get("source") {
        msg.source = from_json_event_source(&value.to_string()).map_err(|e| e.to_string())?;
    }

    if let Some(value) = obj.get("timestamp") {
        msg.timestamp = from_json_timestamp(&value.to_string()).map_err(|e| e.to_string())?;
    }

    if let Some(value) = obj.get("attributes") {
    let map_obj = value.as_object().ok_or_else(|| "expected object".to_string())?;
    msg.attributes = std::collections::HashMap::new();
    for (key_str, val) in map_obj {
        let k = key_str.to_string();
        let mut v: String = Default::default();
        v = val.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
        msg.attributes.insert(k, v);
    }
    }

    if let Some(value) = obj.get("payload") {
        if value.is_null() {
            msg.payload = None;
        } else {
            let mut v: Vec<u8> = Default::default();
                    let s = value.as_str().ok_or_else(|| "expected string".to_string())?;
            v = cramberry::json::decode_base64(s).map_err(|e| e.to_string())?;
            msg.payload = Some(v);
        }
    }

    if let Some(value) = obj.get("correlation_id") {
        if value.is_null() {
            msg.correlation_id = None;
        } else {
            let mut v: String = Default::default();
                    v = value.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
            msg.correlation_id = Some(v);
        }
    }

    if let Some(value) = obj.get("causation_id") {
        if value.is_null() {
            msg.causation_id = None;
        } else {
            let mut v: String = Default::default();
                    v = value.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
            msg.causation_id = Some(v);
        }
    }


    Ok(msg)
}


/// LogEntry represents a log message.
#[derive(Debug, Clone, PartialEq, Default)]
#[derive(Serialize, Deserialize)]
pub struct LogEntry {
    #[serde(rename = "timestamp")]
    pub timestamp: Timestamp,
    #[serde(rename = "level")]
    pub level: String,
    #[serde(rename = "logger")]
    pub logger: String,
    #[serde(rename = "msg")]
    pub msg: String,
    #[serde(rename = "source")]
    pub source: EventSource,
    #[serde(rename = "fields")]
    pub fields: std::collections::HashMap<String, String>,
    #[serde(rename = "stack_trace")]
    pub stack_trace: Option<String>,
    #[serde(rename = "trace_id")]
    pub trace_id: Option<String>,
    #[serde(rename = "span_id")]
    pub span_id: Option<String>,
}

/// Encodes a LogEntry to the writer.
pub fn encode_log_entry(writer: &mut Writer, msg: &LogEntry) -> Result<()> {

    // Field 1: timestamp
    writer.write_tag(1, WireType::Bytes)?;
    {
        let __cp = writer.begin_message();
        encode_timestamp(writer, &msg.timestamp)?;
        writer.end_message(__cp);
        Ok::<(), cramberry::Error>(())
    }?;

    // Field 2: level
    if !msg.level.is_empty() {
        writer.write_tag(2, WireType::Bytes)?;
        writer.write_string(&msg.level)?;
    }

    // Field 3: logger
    if !msg.logger.is_empty() {
        writer.write_tag(3, WireType::Bytes)?;
        writer.write_string(&msg.logger)?;
    }

    // Field 4: msg
    if !msg.msg.is_empty() {
        writer.write_tag(4, WireType::Bytes)?;
        writer.write_string(&msg.msg)?;
    }

    // Field 5: source
    writer.write_tag(5, WireType::Bytes)?;
    {
        let __cp = writer.begin_message();
        encode_event_source(writer, &msg.source)?;
        writer.end_message(__cp);
        Ok::<(), cramberry::Error>(())
    }?;

    // Field 6: fields
    writer.write_tag(6, WireType::Bytes)?;
    {
        use cramberry::CompareKeys;
        let mut __entries: Vec<_> = msg.fields.iter().collect();
        __entries.sort_by(|a, b| a.0.cramberry_cmp(b.0));
        let __cp = writer.begin_message();
        writer.write_varint(__entries.len() as u32)?;
        for (k, v) in __entries {
            writer.write_string(k)?;
            writer.write_string(v)?;
        }
        writer.end_message(__cp);
        Ok::<(), cramberry::Error>(())
    }?;

    // Field 7: stack_trace
    if msg.stack_trace.is_some() {
        writer.write_tag(7, WireType::Bytes)?;
        {
        let __inner = msg.stack_trace.as_ref().unwrap();
        writer.write_string(&(*__inner))
    }?;
    }

    // Field 8: trace_id
    if msg.trace_id.is_some() {
        writer.write_tag(8, WireType::Bytes)?;
        {
        let __inner = msg.trace_id.as_ref().unwrap();
        writer.write_string(&(*__inner))
    }?;
    }

    // Field 9: span_id
    if msg.span_id.is_some() {
        writer.write_tag(9, WireType::Bytes)?;
        {
        let __inner = msg.span_id.as_ref().unwrap();
        writer.write_string(&(*__inner))
    }?;
    }

    // End marker
    writer.write_end_marker()?;
    Ok(())
}

/// Decodes a LogEntry from the reader.
pub fn decode_log_entry(reader: &mut Reader) -> Result<LogEntry> {
    let mut timestamp: Timestamp = Default::default();
    let mut level: String = Default::default();
    let mut logger: String = Default::default();
    let mut msg: String = Default::default();
    let mut source: EventSource = Default::default();
    let mut fields: std::collections::HashMap<String, String> = Default::default();
    let mut stack_trace: Option<String> = Default::default();
    let mut trace_id: Option<String> = Default::default();
    let mut span_id: Option<String> = Default::default();

    loop {
        let tag = reader.read_tag()?;
        if tag.field_number == 0 { break; } // End marker

        match tag.field_number {
            1 => timestamp = {
            let __data = reader.read_length_prefixed_bytes()?;
            let mut __sub = Reader::new(__data);
            decode_timestamp(&mut __sub)?
        },
            2 => level = reader.read_string()?.to_string(),
            3 => logger = reader.read_string()?.to_string(),
            4 => msg = reader.read_string()?.to_string(),
            5 => source = {
            let __data = reader.read_length_prefixed_bytes()?;
            let mut __sub = Reader::new(__data);
            decode_event_source(&mut __sub)?
        },
            6 => fields = {
            let __data = reader.read_length_prefixed_bytes()?;
            let mut reader = Reader::new(__data);
            let len = reader.read_varint()? as usize;
            let mut result = std::collections::HashMap::with_capacity(len);
            for _ in 0..len {
                let k = reader.read_string()?.to_string();
                let v = reader.read_string()?.to_string();
                result.insert(k, v);
            }
            result
        },
            7 => stack_trace = Some(reader.read_string()?.to_string()),
            8 => trace_id = Some(reader.read_string()?.to_string()),
            9 => span_id = Some(reader.read_string()?.to_string()),
            _ => reader.skip_value(tag.wire_type)?,
        }
    }

    Ok(LogEntry {
        timestamp,
        level,
        logger,
        msg,
        source,
        fields,
        stack_trace,
        trace_id,
        span_id,
    })
}

/// Marshals a LogEntry to bytes.
pub fn marshal_log_entry(msg: &LogEntry) -> Result<Vec<u8>> {
    let mut writer = Writer::new();
    encode_log_entry(&mut writer, msg)?;
    Ok(writer.into_bytes())
}

/// Unmarshals a LogEntry from bytes.
pub fn unmarshal_log_entry(data: &[u8]) -> Result<LogEntry> {
    let mut reader = Reader::new(data);
    decode_log_entry(&mut reader)
}

/// Encodes a LogEntry to deterministic JSON format.
pub fn to_json_log_entry(msg: &LogEntry) -> std::result::Result<String, String> {
    let mut result = String::new();
    result.push_str("{");

    result.push_str("\"timestamp\":");
    result.push_str(&to_json_timestamp(&msg.timestamp)?);

    result.push_str(",");
    result.push_str("\"level\":");
    result.push_str(&cramberry::json::escape_json_string(&msg.level));

    result.push_str(",");
    result.push_str("\"logger\":");
    result.push_str(&cramberry::json::escape_json_string(&msg.logger));

    result.push_str(",");
    result.push_str("\"msg\":");
    result.push_str(&cramberry::json::escape_json_string(&msg.msg));

    result.push_str(",");
    result.push_str("\"source\":");
    result.push_str(&to_json_event_source(&msg.source)?);

    result.push_str(",");
    result.push_str("\"fields\":");
    {
        result.push_str("{");
        let mut keys: Vec<String> = msg.fields.keys().map(|k| k.to_string()).collect();
        cramberry::json::sort_map_keys_lexicographic(&mut keys);
        for (i, key_str) in keys.iter().enumerate() {
            if i > 0 { result.push_str(","); }
            result.push_str(&cramberry::json::escape_json_string(key_str));
            result.push_str(":");
            let k = key_str.as_str();
            let v = msg.fields.get(k).unwrap();
            result.push_str(&cramberry::json::escape_json_string(&(*v)));
        }
        result.push_str("}");
    }

    result.push_str(",");
    result.push_str("\"stack_trace\":");
    if let Some(v) = &msg.stack_trace {
            result.push_str(&cramberry::json::escape_json_string(&v));
    } else {
        result.push_str("null");
    }

    result.push_str(",");
    result.push_str("\"trace_id\":");
    if let Some(v) = &msg.trace_id {
            result.push_str(&cramberry::json::escape_json_string(&v));
    } else {
        result.push_str("null");
    }

    result.push_str(",");
    result.push_str("\"span_id\":");
    if let Some(v) = &msg.span_id {
            result.push_str(&cramberry::json::escape_json_string(&v));
    } else {
        result.push_str("null");
    }

    result.push_str("}");
    Ok(result)
}

