/// Decodes a UserProfile from JSON format.
pub fn from_json_user_profile(json: &str) -> std::result::Result<UserProfile, String> {
    let parsed: serde_json::Value = serde_json::from_str(json)
        .map_err(|e| format!("JSON parse error: {}", e))?;

    let obj = parsed.as_object()
        .ok_or_else(|| "expected JSON object".to_string())?;

    // Check for unknown fields (strict mode). Use a match on a static
    // slice instead of a HashSet — for the typical small field count
    // (<20) the linear scan is faster and avoids the per-call HashSet
    // allocation that the previous codegen emitted.
    for key in obj.keys() {
        match key.as_str() {
            "id" => {},
            "username" => {},
            "email" => {},
            "display_name" => {},
            "bio" => {},
            "avatar_url" => {},
            "personal_info" => {},
            "account_status" => {},
            "roles" => {},
            "permissions" => {},
            "preferences" => {},
            "settings" => {},
            "organizations" => {},
            "documents" => {},
            "recent_activity" => {},
            "usage_metrics" => {},
            "created_at" => {},
            "last_login_at" => {},
            "deleted_at" => {},
            other => return Err(format!("unknown field: {}", other)),
        }
    }

    let mut msg: UserProfile = Default::default();

    // Decode fields

    if let Some(value) = obj.get("id") {
        msg.id = cramberry::json::parse_i64_from_json(value)?;
    }

    if let Some(value) = obj.get("username") {
        msg.username = value.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
    }

    if let Some(value) = obj.get("email") {
        msg.email = value.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
    }

    if let Some(value) = obj.get("display_name") {
        msg.display_name = value.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
    }

    if let Some(value) = obj.get("bio") {
        if value.is_null() {
            msg.bio = None;
        } else {
            let mut v: String = Default::default();
                    v = value.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
            msg.bio = Some(v);
        }
    }

    if let Some(value) = obj.get("avatar_url") {
        if value.is_null() {
            msg.avatar_url = None;
        } else {
            let mut v: String = Default::default();
                    v = value.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
            msg.avatar_url = Some(v);
        }
    }

    if let Some(value) = obj.get("personal_info") {
        msg.personal_info = from_json_person(&value.to_string()).map_err(|e| e.to_string())?;
    }

    if let Some(value) = obj.get("account_status") {
        let str_val = value.as_str().ok_or_else(|| "expected string for enum".to_string())?;
        msg.account_status = match str_val {
            "UNKNOWN" => Status::Unknown,
            "PENDING" => Status::Pending,
            "ACTIVE" => Status::Active,
            "SUSPENDED" => Status::Suspended,
            "DELETED" => Status::Deleted,
            _ => return Err(format!("unknown enum value: {}", str_val)),
        };
    }

    if let Some(value) = obj.get("roles") {
    let arr = value.as_array().ok_or_else(|| "expected array".to_string())?;
    msg.roles = Vec::new();
    for elem in arr {
        let mut decoded: String = Default::default();
        decoded = elem.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
        msg.roles.push(decoded);
    }
    }

    if let Some(value) = obj.get("permissions") {
    let arr = value.as_array().ok_or_else(|| "expected array".to_string())?;
    msg.permissions = Vec::new();
    for elem in arr {
        let mut decoded: String = Default::default();
        decoded = elem.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
        msg.permissions.push(decoded);
    }
    }

    if let Some(value) = obj.get("preferences") {
    let map_obj = value.as_object().ok_or_else(|| "expected object".to_string())?;
    msg.preferences = std::collections::HashMap::new();
    for (key_str, val) in map_obj {
        let k = key_str.to_string();
        let mut v: String = Default::default();
        v = val.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
        msg.preferences.insert(k, v);
    }
    }

    if let Some(value) = obj.get("settings") {
    let map_obj = value.as_object().ok_or_else(|| "expected object".to_string())?;
    msg.settings = std::collections::HashMap::new();
    for (key_str, val) in map_obj {
        let k = key_str.to_string();
        let mut v: String = Default::default();
        v = val.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
        msg.settings.insert(k, v);
    }
    }

    if let Some(value) = obj.get("organizations") {
    let arr = value.as_array().ok_or_else(|| "expected array".to_string())?;
    msg.organizations = Vec::new();
    for elem in arr {
        let mut decoded: Organization = Default::default();
        decoded = from_json_organization(&elem.to_string()).map_err(|e| e.to_string())?;
        msg.organizations.push(decoded);
    }
    }

    if let Some(value) = obj.get("documents") {
    let arr = value.as_array().ok_or_else(|| "expected array".to_string())?;
    msg.documents = Vec::new();
    for elem in arr {
        let mut decoded: Document = Default::default();
        decoded = from_json_document(&elem.to_string()).map_err(|e| e.to_string())?;
        msg.documents.push(decoded);
    }
    }

    if let Some(value) = obj.get("recent_activity") {
    let arr = value.as_array().ok_or_else(|| "expected array".to_string())?;
    msg.recent_activity = Vec::new();
    for elem in arr {
        let mut decoded: Event = Default::default();
        decoded = from_json_event(&elem.to_string()).map_err(|e| e.to_string())?;
        msg.recent_activity.push(decoded);
    }
    }

    if let Some(value) = obj.get("usage_metrics") {
        msg.usage_metrics = from_json_metrics(&value.to_string()).map_err(|e| e.to_string())?;
    }

    if let Some(value) = obj.get("created_at") {
        msg.created_at = from_json_timestamp(&value.to_string()).map_err(|e| e.to_string())?;
    }

    if let Some(value) = obj.get("last_login_at") {
        msg.last_login_at = from_json_timestamp(&value.to_string()).map_err(|e| e.to_string())?;
    }

    if let Some(value) = obj.get("deleted_at") {
        if value.is_null() {
            msg.deleted_at = None;
        } else {
            let mut v: Timestamp = Default::default();
                    v = from_json_timestamp(&value.to_string()).map_err(|e| e.to_string())?;
            msg.deleted_at = Some(v);
        }
    }


    Ok(msg)
}


/// BatchRequest contains multiple items for batch processing.
#[derive(Debug, Clone, PartialEq, Default)]
#[derive(Serialize, Deserialize)]
pub struct BatchRequest {
    #[serde(rename = "request_id")]
    pub request_id: String,
    #[serde(rename = "items")]
    pub items: Vec<SmallMessage>,
    #[serde(rename = "headers")]
    pub headers: std::collections::HashMap<String, String>,
    #[serde(rename = "submitted_at")]
    pub submitted_at: Timestamp,
    #[serde(rename = "timeout")]
    pub timeout: Option<Duration>,
    #[serde(rename = "priority")]
    pub priority: Priority,
}

/// Encodes a BatchRequest to the writer.
pub fn encode_batch_request(writer: &mut Writer, msg: &BatchRequest) -> Result<()> {

    // Field 1: request_id
    if !msg.request_id.is_empty() {
        writer.write_tag(1, WireType::Bytes)?;
        writer.write_string(&msg.request_id)?;
    }

    // Field 2: items
    if !msg.items.is_empty() {
        writer.write_tag(2, WireType::Bytes)?;
        {
        let __cp = writer.begin_message();
        writer.write_varint(msg.items.len() as u32)?;
        for elem in &msg.items {
            encode_small_message(writer, elem)?;
        }
        writer.end_message(__cp);
        Ok::<(), cramberry::Error>(())
    }?;
    }

    // Field 3: headers
    writer.write_tag(3, WireType::Bytes)?;
    {
        use cramberry::CompareKeys;
        let mut __entries: Vec<_> = msg.headers.iter().collect();
        __entries.sort_by(|a, b| a.0.cramberry_cmp(b.0));
        let __cp = writer.begin_message();
        writer.write_varint(__entries.len() as u32)?;
        for (k, v) in __entries {
            writer.write_string(k)?;
            writer.write_string(v)?;
        }
        writer.end_message(__cp);
        Ok::<(), cramberry::Error>(())
    }?;

    // Field 4: submitted_at
    writer.write_tag(4, WireType::Bytes)?;
    {
        let __cp = writer.begin_message();
        encode_timestamp(writer, &msg.submitted_at)?;
        writer.end_message(__cp);
        Ok::<(), cramberry::Error>(())
    }?;

    // Field 5: timeout
    if msg.timeout.is_some() {
        writer.write_tag(5, WireType::Bytes)?;
        {
        let __inner = msg.timeout.as_ref().unwrap();
        {
        let __cp = writer.begin_message();
        encode_duration(writer, &(*__inner))?;
        writer.end_message(__cp);
        Ok::<(), cramberry::Error>(())
    }
    }?;
    }

    // Field 6: priority
    writer.write_tag(6, WireType::SVarint)?;
    writer.write_svarint(msg.priority as i32)?;

    // End marker
    writer.write_end_marker()?;
    Ok(())
}

/// Decodes a BatchRequest from the reader.
pub fn decode_batch_request(reader: &mut Reader) -> Result<BatchRequest> {
    let mut request_id: String = Default::default();
    let mut items: Vec<SmallMessage> = Default::default();
    let mut headers: std::collections::HashMap<String, String> = Default::default();
    let mut submitted_at: Timestamp = Default::default();
    let mut timeout: Option<Duration> = Default::default();
    let mut priority: Priority = Default::default();

    loop {
        let tag = reader.read_tag()?;
        if tag.field_number == 0 { break; } // End marker

        match tag.field_number {
            1 => request_id = reader.read_string()?.to_string(),
            2 => items = {
            let __data = reader.read_length_prefixed_bytes()?;
            let mut reader = Reader::new(__data);
            let len = reader.read_varint()? as usize;
            let mut result = Vec::with_capacity(len);
            for _ in 0..len {
                result.push(decode_small_message(&mut reader)?);
            }
            result
        },
            3 => headers = {
            let __data = reader.read_length_prefixed_bytes()?;
            let mut reader = Reader::new(__data);
            let len = reader.read_varint()? as usize;
            let mut result = std::collections::HashMap::with_capacity(len);
            for _ in 0..len {
                let k = reader.read_string()?.to_string();
                let v = reader.read_string()?.to_string();
                result.insert(k, v);
            }
            result
        },
            4 => submitted_at = {
            let __data = reader.read_length_prefixed_bytes()?;
            let mut __sub = Reader::new(__data);
            decode_timestamp(&mut __sub)?
        },
            5 => timeout = Some({
            let __data = reader.read_length_prefixed_bytes()?;
            let mut __sub = Reader::new(__data);
            decode_duration(&mut __sub)?
        }),
            6 => priority = Priority::from_i32(reader.read_svarint()?).unwrap_or(Priority::Low),
            _ => reader.skip_value(tag.wire_type)?,
        }
    }

    Ok(BatchRequest {
        request_id,
        items,
        headers,
        submitted_at,
        timeout,
        priority,
    })
}

/// Marshals a BatchRequest to bytes.
pub fn marshal_batch_request(msg: &BatchRequest) -> Result<Vec<u8>> {
    let mut writer = Writer::new();
    encode_batch_request(&mut writer, msg)?;
    Ok(writer.into_bytes())
}

/// Unmarshals a BatchRequest from bytes.
pub fn unmarshal_batch_request(data: &[u8]) -> Result<BatchRequest> {
    let mut reader = Reader::new(data);
    decode_batch_request(&mut reader)
}

/// Encodes a BatchRequest to deterministic JSON format.
pub fn to_json_batch_request(msg: &BatchRequest) -> std::result::Result<String, String> {
    let mut result = String::new();
    result.push_str("{");

    result.push_str("\"request_id\":");
    result.push_str(&cramberry::json::escape_json_string(&msg.request_id));

    result.push_str(",");
    result.push_str("\"items\":");
    result.push_str("[");
    for (i, elem) in msg.items.iter().enumerate() {
        if i > 0 { result.push_str(","); }
        result.push_str(&to_json_small_message(&(*elem))?);
    }
    result.push_str("]");

    result.push_str(",");
    result.push_str("\"headers\":");
    {
        result.push_str("{");
        let mut keys: Vec<String> = msg.headers.keys().map(|k| k.to_string()).collect();
        cramberry::json::sort_map_keys_lexicographic(&mut keys);
        for (i, key_str) in keys.iter().enumerate() {
            if i > 0 { result.push_str(","); }
            result.push_str(&cramberry::json::escape_json_string(key_str));
            result.push_str(":");
            let k = key_str.as_str();
            let v = msg.headers.get(k).unwrap();
            result.push_str(&cramberry::json::escape_json_string(&(*v)));
        }
        result.push_str("}");
    }

    result.push_str(",");
    result.push_str("\"submitted_at\":");
    result.push_str(&to_json_timestamp(&msg.submitted_at)?);

    result.push_str(",");
    result.push_str("\"timeout\":");
    if let Some(v) = &msg.timeout {
            result.push_str(&to_json_duration(&v)?);
    } else {
        result.push_str("null");
    }

    result.push_str(",");
    result.push_str("\"priority\":");
    result.push_str("\"");
    result.push_str(match msg.priority {
        Priority::Low => "LOW",
        Priority::Medium => "MEDIUM",
        Priority::High => "HIGH",
        Priority::Critical => "CRITICAL",
        _ => "UNKNOWN",
    });
    result.push_str("\"");

    result.push_str("}");
    Ok(result)
}

/// Decodes a BatchRequest from JSON format.
pub fn from_json_batch_request(json: &str) -> std::result::Result<BatchRequest, String> {
    let parsed: serde_json::Value = serde_json::from_str(json)
        .map_err(|e| format!("JSON parse error: {}", e))?;

    let obj = parsed.as_object()
        .ok_or_else(|| "expected JSON object".to_string())?;

    // Check for unknown fields (strict mode). Use a match on a static
    // slice instead of a HashSet — for the typical small field count
    // (<20) the linear scan is faster and avoids the per-call HashSet
    // allocation that the previous codegen emitted.
    for key in obj.keys() {
        match key.as_str() {
            "request_id" => {},
            "items" => {},
            "headers" => {},
            "submitted_at" => {},
            "timeout" => {},
            "priority" => {},
            other => return Err(format!("unknown field: {}", other)),
        }
    }

    let mut msg: BatchRequest = Default::default();

    // Decode fields

    if let Some(value) = obj.get("request_id") {
        msg.request_id = value.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
    }

    if let Some(value) = obj.get("items") {
    let arr = value.as_array().ok_or_else(|| "expected array".to_string())?;
    msg.items = Vec::new();
    for elem in arr {
        let mut decoded: SmallMessage = Default::default();
        decoded = from_json_small_message(&elem.to_string()).map_err(|e| e.to_string())?;
        msg.items.push(decoded);
    }
    }

    if let Some(value) = obj.get("headers") {
    let map_obj = value.as_object().ok_or_else(|| "expected object".to_string())?;
    msg.headers = std::collections::HashMap::new();
    for (key_str, val) in map_obj {
        let k = key_str.to_string();
        let mut v: String = Default::default();
        v = val.as_str().ok_or_else(|| "expected string".to_string())?.to_string();
        msg.headers.insert(k, v);
    }
    }

    if let Some(value) = obj.get("submitted_at") {
        msg.submitted_at = from_json_timestamp(&value.to_string()).map_err(|e| e.to_string())?;
    }

    if let Some(value) = obj.get("timeout") {
        if value.is_null() {
            msg.timeout = None;
        } else {
            let mut v: Duration = Default::default();
                    v = from_json_duration(&value.to_string()).map_err(|e| e.to_string())?;
            msg.timeout = Some(v);
        }
    }

    if let Some(value) = obj.get("priority") {
        let str_val = value.as_str().ok_or_else(|| "expected string for enum".to_string())?;
        msg.priority = match str_val {
            "LOW" => Priority::Low,
            "MEDIUM" => Priority::Medium,
            "HIGH" => Priority::High,
            "CRITICAL" => Priority::Critical,
            _ => return Err(format!("unknown enum value: {}", str_val)),
        };
    }


    Ok(msg)
}


/// BatchResponse contains results from batch processing.
#[derive(Debug, Clone, PartialEq, Default)]
#[derive(Serialize, Deserialize)]
pub struct BatchResponse {
    #[serde(rename = "request_id")]
    pub request_id: String,
    #[serde(rename = "results")]
    pub results: Vec<SmallMessage>,
    #[serde(rename = "errors")]
    pub errors: Vec<String>,
    #[serde(rename = "processing_metrics")]
    pub processing_metrics: Metrics,
    #[serde(rename = "processing_time")]
    pub processing_time: Duration,
    #[serde(rename = "completed_at")]
    pub completed_at: Timestamp,
}

/// Encodes a BatchResponse to the writer.
pub fn encode_batch_response(writer: &mut Writer, msg: &BatchResponse) -> Result<()> {

    // Field 1: request_id
    if !msg.request_id.is_empty() {
        writer.write_tag(1, WireType::Bytes)?;
        writer.write_string(&msg.request_id)?;
    }

    // Field 2: results
    if !msg.results.is_empty() {
        writer.write_tag(2, WireType::Bytes)?;
        {
        let __cp = writer.begin_message();
        writer.write_varint(msg.results.len() as u32)?;
        for elem in &msg.results {
            encode_small_message(writer, elem)?;
        }
        writer.end_message(__cp);
        Ok::<(), cramberry::Error>(())
    }?;
    }

    // Field 3: errors
    if !msg.errors.is_empty() {
        writer.write_tag(3, WireType::Bytes)?;
        {
        let __cp = writer.begin_message();
        writer.write_varint(msg.errors.len() as u32)?;
        for elem in &msg.errors {
            writer.write_string(elem)?;
        }
        writer.end_message(__cp);
        Ok::<(), cramberry::Error>(())
    }?;
    }

    // Field 4: processing_metrics
    writer.write_tag(4, WireType::Bytes)?;
    {
        let __cp = writer.begin_message();
        encode_metrics(writer, &msg.processing_metrics)?;
        writer.end_message(__cp);
        Ok::<(), cramberry::Error>(())
    }?;

    // Field 5: processing_time
    writer.write_tag(5, WireType::Bytes)?;
    {
        let __cp = writer.begin_message();
        encode_duration(writer, &msg.processing_time)?;
        writer.end_message(__cp);
        Ok::<(), cramberry::Error>(())
    }?;

    // Field 6: completed_at
    writer.write_tag(6, WireType::Bytes)?;
    {
        let __cp = writer.begin_message();
        encode_timestamp(writer, &msg.completed_at)?;
        writer.end_message(__cp);
        Ok::<(), cramberry::Error>(())
    }?;

    // End marker
    writer.write_end_marker()?;
    Ok(())
}

/// Decodes a BatchResponse from the reader.
pub fn decode_batch_response(reader: &mut Reader) -> Result<BatchResponse> {
    let mut request_id: String = Default::default();
    let mut results: Vec<SmallMessage> = Default::default();
    let mut errors: Vec<String> = Default::default();
    let mut processing_metrics: Metrics = Default::default();
    let mut processing_time: Duration = Default::default();
    let mut completed_at: Timestamp = Default::default();

    loop {
        let tag = reader.read_tag()?;
        if tag.field_number == 0 { break; } // End marker

        match tag.field_number {
            1 => request_id = reader.read_string()?.to_string(),
            2 => results = {
            let __data = reader.read_length_prefixed_bytes()?;
            let mut reader = Reader::new(__data);
            let len = reader.read_varint()? as usize;
            let mut result = Vec::with_capacity(len);
            for _ in 0..len {
                result.push(decode_small_message(&mut reader)?);
            }
            result
        },
            3 => errors = {
            let __data = reader.read_length_prefixed_bytes()?;
            let mut reader = Reader::new(__data);
            let len = reader.read_varint()? as usize;
            let mut result = Vec::with_capacity(len);
            for _ in 0..len {
                result.push(reader.read_string()?.to_string());
            }
            result
        },
            4 => processing_metrics = {
            let __data = reader.read_length_prefixed_bytes()?;
            let mut __sub = Reader::new(__data);
            decode_metrics(&mut __sub)?
        },
            5 => processing_time = {
            let __data = reader.read_length_prefixed_bytes()?;
            let mut __sub = Reader::new(__data);
            decode_duration(&mut __sub)?
        },
            6 => completed_at = {
            let __data = reader.read_length_prefixed_bytes()?;
            let mut __sub = Reader::new(__data);
            decode_timestamp(&mut __sub)?
        },
            _ => reader.skip_value(tag.wire_type)?,
        }
    }

    Ok(BatchResponse {
        request_id,
        results,
        errors,
        processing_metrics,
        processing_time,
        completed_at,
    })
}

/// Marshals a BatchResponse to bytes.
pub fn marshal_batch_response(msg: &BatchResponse) -> Result<Vec<u8>> {
    let mut writer = Writer::new();
    encode_batch_response(&mut writer, msg)?;
    Ok(writer.into_bytes())
}

/// Unmarshals a BatchResponse from bytes.
pub fn unmarshal_batch_response(data: &[u8]) -> Result<BatchResponse> {
    let mut reader = Reader::new(data);
    decode_batch_response(&mut reader)
}

/// Encodes a BatchResponse to deterministic JSON format.
pub fn to_json_batch_response(msg: &BatchResponse) -> std::result::Result<String, String> {
    let mut result = String::new();
    result.push_str("{");

    result.push_str("\"request_id\":");
    result.push_str(&cramberry::json::escape_json_string(&msg.request_id));

    result.push_str(",");
    result.push_str("\"results\":");
    result.push_str("[");
    for (i, elem) in msg.results.iter().enumerate() {
        if i > 0 { result.push_str(","); }
        result.push_str(&to_json_small_message(&(*elem))?);
    }
    result.push_str("]");

    result.push_str(",");
    result.push_str("\"errors\":");
    result.push_str("[");
    for (i, elem) in msg.errors.iter().enumerate() {
        if i > 0 { result.push_str(","); }
        result.push_str(&cramberry::json::escape_json_string(&(*elem)));
    }
    result.push_str("]");

    result.push_str(",");
    result.push_str("\"processing_metrics\":");
    result.push_str(&to_json_metrics(&msg.processing_metrics)?);

    result.push_str(",");
    result.push_str("\"processing_time\":");
    result.push_str(&to_json_duration(&msg.processing_time)?);

    result.push_str(",");
    result.push_str("\"completed_at\":");
    result.push_str(&to_json_timestamp(&msg.completed_at)?);

    result.push_str("}");
    Ok(result)
}

